document.addEventListener('DOMContentLoaded',()=>{const themeToggle=document.getElementById('theme-toggle');const themeIcon=themeToggle ? themeToggle.querySelector('i'): null;const storedTheme=localStorage.getItem('theme');const prefersDark=window.matchMedia('(prefers-color-scheme: dark)').matches;const initialTheme=storedTheme ||(prefersDark ? 'dark' : 'light');document.documentElement.setAttribute('data-theme',initialTheme);updateThemeIcon(initialTheme);if(themeToggle){themeToggle.addEventListener('click',()=>{const currentTheme=document.documentElement.getAttribute('data-theme');const newTheme=currentTheme==='dark' ? 'light' : 'dark';document.documentElement.setAttribute('data-theme',newTheme);localStorage.setItem('theme',newTheme);updateThemeIcon(newTheme);});}function updateThemeIcon(theme){if(!themeIcon)return;if(theme==='dark'){themeIcon.classList.remove('fa-moon');themeIcon.classList.add('fa-sun');}else{themeIcon.classList.remove('fa-sun');themeIcon.classList.add('fa-moon');}}const filterButtons=document.querySelectorAll('.filter-btn');const projectCards=document.querySelectorAll('.project-card');filterButtons.forEach(button=>{button.addEventListener('click',()=>{filterButtons.forEach(btn=>btn.classList.remove('active'));button.classList.add('active');const filterValue=button.getAttribute('data-filter');projectCards.forEach(card=>{const categories=(card.getAttribute('data-category')|| '').split(' ');if(filterValue==='all' || categories.includes(filterValue)){card.classList.remove('hidden');}else{card.classList.add('hidden');}});});});const header=document.querySelector('.main-header');function handleScroll(){if(!header)return;if(window.scrollY>40){header.classList.add('scrolled');}else{header.classList.remove('scrolled');}}window.addEventListener('scroll',handleScroll,{passive: true});handleScroll();const hamburger=document.querySelector('.hamburger-menu');const navMenu=document.querySelector('.main-nav');const navLinks=document.querySelectorAll('.main-nav ul li a');if(hamburger && navMenu){hamburger.addEventListener('click',()=>{const isActive=hamburger.classList.toggle('is-active');navMenu.classList.toggle('is-active');document.body.style.overflow=isActive ? 'hidden' : '';});navLinks.forEach(link=>{link.addEventListener('click',()=>{hamburger.classList.remove('is-active');navMenu.classList.remove('is-active');document.body.style.overflow='';});});}const catTrigger=document.getElementById('cat-avatar-trigger');const catBubble=document.getElementById('cat-speech-bubble');const catQuote=document.getElementById('cat-quote-text');const catCounter=document.getElementById('cat-quote-counter');const catQuotes=[ "All comms encrypted. Leave your coordinates below. Meow.","Arbitrum Nitro full node is fully synced. 0 lost ticks in mempool.","Reverse proxy handles all session conflicts. Your cookies are safe with me.","48,000 UAH earned on Rust DEX engine... all allocated for premium salmon treats.","I personally code-review every git commit before Yevhen pushes to master.","Zero corporate AI bloat detected. Pure engineering and street style verified.","Purr... You unlocked the Sentinel Cat buff:+10 luck on your next production deploy." ];let currentQuoteIndex=0;function triggerCatPurr(){if(!catTrigger || !catQuote)return;currentQuoteIndex=(currentQuoteIndex+1)% catQuotes.length;catTrigger.classList.add('purring');setTimeout(()=>catTrigger.classList.remove('purring'),600);catQuote.style.opacity='0';setTimeout(()=>{catQuote.textContent=`"${catQuotes[currentQuoteIndex]}"`;if(catCounter){catCounter.textContent=`[0${currentQuoteIndex+1}/0${catQuotes.length}]`;}catQuote.style.opacity='1';},150);}if(catTrigger){catTrigger.addEventListener('click',triggerCatPurr);}if(catBubble){catBubble.addEventListener('click',triggerCatPurr);}});